-- ONE statement. Run only at the documented step; do not also run master 02.
USE auxiliares;
ALTER TABLE FB_PERSONAS
 MODIFY DOCUMENTO_NORMALIZADO VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin GENERATED ALWAYS AS (UPPER(REGEXP_REPLACE(TRIM(DOCUMENTO), '[-.[:space:]]', ''))) STORED,
 ADD VERIFICACION_CP_JSON JSON NULL,
 ADD DOCUMENTO_IDENTIDAD_UNICA VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN TIPO_DOCUMENTO IN ('CEDULA_IDENTIDAD','RUT') THEN UPPER(REGEXP_REPLACE(TRIM(DOCUMENTO), '[-.[:space:]]', '')) ELSE NULL END) STORED,
 ADD UNIQUE KEY UK_FB_PERSONAS_DOCUMENTO (TIPO_DOCUMENTO,DOCUMENTO_IDENTIDAD_UNICA),
 ADD UNIQUE KEY UK_71_PERSONA_CP (ID_PERSONA,ID_PERSONA_CP),
 ADD CONSTRAINT CHK_71_PERSONA_DOC CHECK (TIPO_DOCUMENTO IN ('CEDULA_IDENTIDAD','RUT','OTROS') AND ((TIPO_DOCUMENTO='CEDULA_IDENTIDAD' AND DOCUMENTO_NORMALIZADO REGEXP '^[0-9]{7,8}$') OR (TIPO_DOCUMENTO='RUT' AND DOCUMENTO_NORMALIZADO REGEXP '^[0-9]{12}$') OR (TIPO_DOCUMENTO='OTROS' AND CHAR_LENGTH(DOCUMENTO_NORMALIZADO)>0))),
 ADD CONSTRAINT CHK_71_PERSONA_CP CHECK ((ID_PERSONA_CP IS NULL AND VERIFICACION_CP_JSON IS NULL) OR (ID_PERSONA_CP>0 AND VERIFICACION_CP_JSON IS NOT NULL AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(VERIFICACION_CP_JSON,'$.personId'))=CAST(ID_PERSONA_CP AS CHAR) AND JSON_UNQUOTE(JSON_EXTRACT(VERIFICACION_CP_JSON,'$.source'))='institutional',0)));
